solutionCode:
fun isBatteryLow(voltage: Double): Boolean {
    return voltage < 11.0
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testLowBattery() {
        Assert.assertTrue("10.5 should be low", isBatteryLow(10.5))
    }

    @Test
    fun testGoodBattery() {
        Assert.assertFalse("12.0 should not be low", isBatteryLow(12.0))
    }

    @Test
    fun testExactThreshold() {
        Assert.assertFalse("11.0 should not be low", isBatteryLow(11.0))
    }

    @Test
    fun testJustBelow() {
        Assert.assertTrue("10.99 should be low", isBatteryLow(10.99))
    }
}
